import { test, expect } from '@playwright/test';

test.describe('Permissions Error - Editing Another User\'s Content', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display permissions error when attempting to edit another user\'s content', async ({ page }) => {
    // Setup: Log in as user with limited permissions
    await page.goto('/login');
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('limitedUser');
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('password123');
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await loginButton.click();

    // Navigate to another user's profile
    await page.goto('/users/johnDoe');
    const profileName = page.getByRole('heading', { name: /john doe/i });
    await expect(profileName).toBeVisible();

    // Attempt to edit the user's profile
    const editButton = page.getByRole('button', { name: /edit profile/i });
    await expect(editButton).toBeVisible();
    await editButton.click();

    // Verify edit form is visible
    const editForm = page.getByRole('form');
    await expect(editForm).toBeVisible();

    // Attempt to submit the edit form
    const saveButton = page.getByRole('button', { name: /save changes/i });
    await saveButton.click();

    // Verify permissions error message is displayed
    const errorMessage = page.getByText(/permission denied/i);
    await expect(errorMessage).toBeVisible();

    // Verify error details
    const errorDetails = page.getByText(/you do not have permission to edit this content/i);
    await expect(errorDetails).toBeVisible();

    // Verify edit form is still visible but disabled
    await expect(editForm).toBeVisible();
    const nameInput = page.getByLabel('Name');
    await expect(nameInput).toBeDisabled();
  });

